pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 collectAmount, uint256 putValue) public {
        // bound inputs to useful ranges
        unlockTime = bound(unlockTime, 0, 2000000000);
        collectAmount = bound(collectAmount, 0, 10 ether);
        putValue = bound(putValue, 1 ether, 10 ether);

        // Fund test contract
        vm.deal(address(this), 100 ether);

        // Perform Put call from this contract
        c.Put{value: putValue}(unlockTime);

        // Store the unlockTime that should have been set (reference behavior)
        uint256 expectedUnlockTime = unlockTime > block.timestamp ? unlockTime : block.timestamp;

        // Now we need to advance time so that Collect can succeed
        // First, check if we need to advance past unlockTime
        uint256 targetTime = expectedUnlockTime + 1;
        if (block.timestamp < targetTime) {
            vm.warp(targetTime);
        }

        // Attempt Collect with the amount
        // Use try/catch to handle potential reverts
        try c.Collect(collectAmount) {
            // Collect succeeded - check the invariant
            // The unlockTime should not have changed after a Collect
            // Actually, the invariant is: after a Put call that succeeded, 
            // the unlockTime for the sender must equal expectedUnlockTime
            // regardless of subsequent Collect calls
            uint256 actualUnlockTime = c.Acc(address(this)).unlockTime;
            assertTrue(actualUnlockTime == expectedUnlockTime, "unlockTime changed after Collect");
        } catch {
            // Collect reverted - this is fine, but the invariant still holds
            // as state shouldn't change on revert
            // We assert true to pass the test when revert expected
            assertTrue(true);
        }
    }
}

