pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint unlockTime1, uint unlockTime2, uint putValue1, uint putValue2, uint collectAmt) public {
        vm.assume(putValue1 > 0 && putValue2 > 0 && collectAmt > 0);
        vm.assume(putValue1 <= 100 ether && putValue2 <= 100 ether && collectAmt <= 100 ether);
        vm.assume(unlockTime1 <= block.timestamp + 100 && unlockTime2 <= block.timestamp + 100);

        address user = address(0x1234);
        vm.deal(user, 200 ether);

        vm.prank(user);
        c.Put{value: putValue1}(unlockTime1);

        vm.prank(user);
        c.Put{value: putValue2}(unlockTime2);

        uint balanceBefore = address(user).balance;
        uint contractBalanceBefore = address(c).balance;

        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        uint balanceAfter = address(user).balance;
        uint contractBalanceAfter = address(c).balance;

        // General rule: the user's balance change should equal the contract's balance change
        // and the user's balance should not increase more than collectAmt (unless revert)
        if (success) {
            // If Collect succeeded, user must have gotten at most collectAmt
            // and the contract balance decreased by exactly that amount
            assertTrue(balanceAfter - balanceBefore <= collectAmt);
            assertTrue(balanceAfter - balanceBefore == contractBalanceBefore - contractBalanceAfter);
        } else {
            // If reverted, balances unchanged
            assertTrue(balanceAfter == balanceBefore);
            assertTrue(contractBalanceAfter == contractBalanceBefore);
        }
    }
}

