contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // Restrict inputs to reasonable values
        vm.assume(unlockTime <= type(uint40).max);
        vm.assume(amount > 0 && amount <= 100 ether);

        // Fund the contract with at least 1 ether + amount to satisfy MinSum and balance
        vm.deal(address(c), 2 ether + amount);

        // Set the unlock time exactly to current timestamp
        uint256 currentTime = block.timestamp;
        // We will call Put with unlockTime == block.timestamp to set that condition
        // But Put uses max(unlockTime, block.timestamp) so we need to set unlockTime <= currentTime
        // Actually Put sets unlockTime = _unlockTime > block.timestamp ? _unlockTime : block.timestamp
        // So to get unlockTime == block.timestamp, we call Put with _unlockTime = block.timestamp
        // However we need to be called as a specific sender to set their balance
        // Let's use a random sender for the test
        address payable sender = payable(address(0x1234));
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.Put{value: 1 ether}(currentTime); // This sets unlockTime = block.timestamp

        // Now sender has balance >= MinSum (1 ether) and unlockTime == block.timestamp
        // Check account balance before Collect
        (uint256 unlock, uint256 bal) = c.Acc(sender);

        // Attempt Collect with amount <= balance
        uint256 collectAmount = amount <= bal ? amount : (bal > 0 ? bal : 0);
        if (collectAmount == 0) return; // skip trivial case

        // Try to collect when block.timestamp == unlockTime
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The reference (strict >) should revert when timestamp == unlockTime, so success should be false
        // The buggy version (>=) would allow it, so success would be true
        // Our rule: If block.timestamp == unlockTime, then Collect should revert (success == false)
        assertTrue(!success, "Collect should revert when block.timestamp equals unlockTime");
    }
}

