        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After call, total should be unchanged if the implementation is correct
        // (the mutation acc.balance = acc.balance fails to subtract, so total decreases by collectAmount)
        uint totalAfter = c.Acc(sender).balance + address(c).balance;
        assertTrue(totalAfter == totalBefore || totalAfter == totalBefore - collectAmount);
    }
}

