pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(putAmount > 0 && putAmount <= type(uint256).max / 2);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(c.MinSum() <= collectAmount);

        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(unlockTime);

        // Advance time to ensure unlock
        vm.warp(block.timestamp + 1);
        if (unlockTime > block.timestamp) vm.warp(unlockTime + 1);

        uint256 balanceBefore = c.Acc(sender).balance;

        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            assertTrue(c.Acc(sender).balance == balanceBefore - collectAmount, "Balance should decrease by exactly collectAmount");
        } else {
            assertTrue(c.Acc(sender).balance == balanceBefore, "Balance should remain unchanged on revert");
        }
    }
}
